create extension if not exists pgcrypto;
create table profiles (id uuid primary key references auth.users(id), display_name text, created_at timestamptz not null default now());
create table broker_accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), provider text not null, external_account_id text, mode text not null check (mode='PAPER'), status text not null default 'DISCONNECTED', created_at timestamptz not null default now());
create table risk_settings (user_id uuid primary key references profiles(id), settings jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table strategies (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), name text not null, version text not null, enabled boolean not null default false, parameters jsonb not null default '{}'::jsonb);
create table recommendations (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), symbol text not null, direction text not null, score numeric not null, investment numeric not null, stop_loss numeric, take_profit numeric, status text not null default 'PENDING', analysis jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), recommendation_id uuid references recommendations(id), symbol text not null, direction text not null, order_type text not null, quantity numeric not null, status text not null default 'DRAFT', mode text not null check(mode='PAPER'), created_at timestamptz not null default now());
create table positions (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), symbol text not null, direction text not null, entry_price numeric not null, current_price numeric, quantity numeric not null, stop_loss numeric, take_profit numeric, mode text not null check(mode='PAPER'), opened_at timestamptz not null default now());
create table trades (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), order_id uuid references orders(id), position_id uuid references positions(id), symbol text not null, price numeric not null, quantity numeric not null, mode text not null check(mode='PAPER'), executed_at timestamptz not null default now());
create table journal_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), trade_id uuid references trades(id), title text not null, body text not null, created_at timestamptz not null default now());
create table backtests (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), strategy_id uuid references strategies(id), status text not null, metrics jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), type text not null, title text not null, read boolean not null default false, created_at timestamptz not null default now());
create table system_state (user_id uuid primary key references profiles(id), mode text not null default 'PAPER' check(mode='PAPER'), auto_trader_status text not null default 'PAUSED', risk_state text not null default 'NORMAL', emergency_stop_active boolean not null default false, updated_at timestamptz not null default now());
create table audit_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), action text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table profiles enable row level security; alter table broker_accounts enable row level security; alter table risk_settings enable row level security; alter table strategies enable row level security; alter table recommendations enable row level security; alter table orders enable row level security; alter table positions enable row level security; alter table trades enable row level security; alter table journal_entries enable row level security; alter table backtests enable row level security; alter table notifications enable row level security; alter table system_state enable row level security; alter table audit_events enable row level security;
